document.addEventListener('DOMContentLoaded', function() {
    // Add click event listeners to collection headers
    document.querySelectorAll('.collection-header').forEach(function(header) {
        header.addEventListener('click', function() {
            const collectionId = this.getAttribute('data-collection-id');
            const booksContainer = document.getElementById('books-' + collectionId);
            const chevron = document.getElementById('chevron-' + collectionId);

            // Add null checks to prevent errors
            if (!booksContainer || !chevron) {
                console.warn('Missing elements for collection:', collectionId);
                return;
            }

            if (booksContainer.style.display === 'none') {
                // Expand
                booksContainer.style.display = 'block';
                chevron.classList.remove('bi-chevron-right');
                chevron.classList.add('bi-chevron-down');
                this.classList.add('expanded');
                // Set background color based on dark mode
                if (document.body.classList.contains('dark')) {
                    this.style.backgroundColor = '#374151'; // Dark mode expanded
                } else {
                    this.style.backgroundColor = '#d4edda'; // Light mode expanded
                }
            } else {
                // Collapse
                booksContainer.style.display = 'none';
                chevron.classList.remove('bi-chevron-down');
                chevron.classList.add('bi-chevron-right');
                this.classList.remove('expanded');
                // Set background color based on dark mode
                if (document.body.classList.contains('dark')) {
                    this.style.backgroundColor = '#2d3748'; // Dark mode collapsed
                } else {
                    this.style.backgroundColor = '#e8f5e8'; // Light mode collapsed
                }
            }
        });
    });

    // Prevent book buttons from triggering collection header click
    document.querySelectorAll('.hadith-collection-link').forEach(function(button) {
        button.addEventListener('click', function(e) {
            e.stopPropagation(); // Prevent event bubbling to collection header
        });
    });
});


