                    })
                    .catch(error => {
                        console.error('Error fetching narrators:', error);
                        document.getElementById('narratorsModalBody').innerHTML = '<div class="alert alert-danger tamil-custom-font">பிழை ஏற்பட்டது - Error loading narrators</div>';
