     // Helper functions for hadith bookmarks (these should be defined in hadith-bookmark.js)
   function getHadithBookmarks() {
       let bookmarks = JSON.parse(localStorage.getItem('hadithBookmarks')) || [];

       // If it's an old-style array, convert to 5-slot structure
       if (Array.isArray(bookmarks) && (bookmarks.length === 0 || !bookmarks[0] || typeof bookmarks[0].slotNumber === 'undefined')) {
           // Convert to 5-slot structure with empty slots
           const newBookmarks = new Array(5).fill(null).map((_, index) => ({
               slotNumber: index + 1,
               name: `ஹதீஸ் பதிவு ${index + 1}`,
               reference: null,
               hadithNum: null,
               collectionTitle: null,
               dateAdded: null
           }));

           // Fill in existing bookmarks to first available slots
           let slotIndex = 0;
           for (let oldBookmark of bookmarks) {
               if (slotIndex < 5 && oldBookmark && oldBookmark.reference) {
                   newBookmarks[slotIndex] = {
                       slotNumber: slotIndex + 1,
                       name: oldBookmark.name || `ஹதீஸ் பதிவு ${slotIndex + 1}`,
                       reference: oldBookmark.reference,
                       hadithNum: oldBookmark.hadithNum,
                       collectionTitle: oldBookmark.collectionTitle,
                       dateAdded: oldBookmark.dateAdded,
                       collection: oldBookmark.collection,
                       book: oldBookmark.book
                   };
                   slotIndex++;
               }
           }

           localStorage.setItem('hadithBookmarks', JSON.stringify(newBookmarks));
           return newBookmarks;
       }

       // Ensure we always have 5 slots
       if (bookmarks.length < 5) {
           while (bookmarks.length < 5) {
               bookmarks.push({
                   slotNumber: bookmarks.length + 1,
                   name: `ஹதீஸ் பதிவு ${bookmarks.length + 1}`,
                   reference: null,
                   hadithNum: null,
                   collectionTitle: null,
                   dateAdded: null,
                   collection: null,
                   book: null
               });
           }
           localStorage.setItem('hadithBookmarks', JSON.stringify(bookmarks));
       }

       return bookmarks;
   }

