    // Handle hadith explanation modal
    document.addEventListener('click', function (e) {
        if (e.target.closest('.view-hadith-explanation-btn')) {
            e.preventDefault();
            const btn = e.target.closest('.view-hadith-explanation-btn');
            const reference = btn.getAttribute('data-reference');

            // Show the modal
            const explanationModal = new bootstrap.Modal(document.getElementById('hadithExplanationModal'));
            const modalBody = document.getElementById('hadithExplanationModalBody');
            const contentDiv = modalBody.querySelector('.tamil-custom-font');

            // Set loading state
            contentDiv.innerHTML = '<div class="text-center p-3"><div class="spinner-border text-success" role="status"><span class="visually-hidden">Loading...</span></div><p class="mt-2">ஏற்றப்படுகிறது... Loading...</p></div>';
            explanationModal.show();

            // Function to wrap Arabic text with Arabic font styling
            function wrapArabicText(text) {
                if (!text) return '';
                // Arabic Unicode ranges: 0600-06FF, 0750-077F, 08A0-08FF, FB50-FDFF, FE70-FEFF
                const arabicPattern = /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]+/g;
                return text.replace(arabicPattern, '<span class="hadith-arabic-font">$&</span>');
            }

            // Fetch the explanation
            fetch('get_hadith_explanation.php?reference=' + encodeURIComponent(reference))
                .then(response => response.json())
                .then(data => {
                    if (data.success) {
                        contentDiv.innerHTML = wrapArabicText(data.explanation);

                        // Apply font sizes from settings after content is set
                        if (typeof applyFontSizesFromStoredSettings === 'function') {
                            setTimeout(() => applyFontSizesFromStoredSettings(), 100);
                        }
                    } else {
                        contentDiv.innerHTML = '<div class="alert alert-warning">விளக்கம் கிடைக்கவில்லை. Explanation not available.</div>';
                    }
                })
                .catch(error => {
                    console.error('Error fetching explanation:', error);
                    contentDiv.innerHTML = '<div class="alert alert-danger">தகவலைப் பெறுவதில் பிழை ஏற்பட்டது. Error loading explanation.</div>';
                });
        }
    });











        // Auto-scroll to hadith if specified in session storage or window variable
        document.addEventListener('DOMContentLoaded', function () {

            // Setup hadith settings listeners
            if (typeof setupHadithSettingsListeners === 'function') {
                setupHadithSettingsListeners();
            }

            let scrollToHadith = sessionStorage.getItem('scrollToHadith') || window.scrollToHadith;

            // Validate that scrollToHadith is a valid hadith number (numeric or alphanumeric like "100a")
            if (scrollToHadith && (typeof scrollToHadith === 'string' || typeof scrollToHadith === 'number')) {
                // Trim whitespace, remove all spaces, and validate format (allows "100", "100a", "220 a" -> "220a", etc.)
                const trimmedValue = String(scrollToHadith).trim().replace(/\s+/g, '');
                if (!trimmedValue || !/^[0-9]+[a-z]?$/i.test(trimmedValue)) {
                    return;
                }
                scrollToHadith = trimmedValue; // Keep as string to preserve alphanumeric part (normalized)
            }

            if (scrollToHadith) {
                // Clear the session storage
                sessionStorage.removeItem('scrollToHadith');

                // Wait a bit for the page to fully load, then scroll
                setTimeout(() => {
                    // Helper function to normalize hadith numbers (remove spaces)
                    const normalizeHadithNum = (num) => {
                        return String(num).trim().replace(/\s+/g, '');
                    };

                    const normalizedScrollTo = normalizeHadithNum(scrollToHadith);

                    // Try to find the hadith element by the hadith number using data attribute
                    // First try exact match with normalized value
                    let hadithElement = document.querySelector(`[data-hadith-num="${normalizedScrollTo}"]`);

                    if (!hadithElement) {
                        // Try finding by normalizing all data-hadith-num attributes
                        const allHadithElements = document.querySelectorAll('[data-hadith-num]');
                        hadithElement = Array.from(allHadithElements).find(el => {
                            const attrValue = el.getAttribute('data-hadith-num');
                            return normalizeHadithNum(attrValue) === normalizedScrollTo;
                        });
                    }

                    if (hadithElement) {
                        hadithElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        // Add a highlight effect
                        hadithElement.style.backgroundColor = '#fff3cd';
                        setTimeout(() => {
                            hadithElement.style.backgroundColor = '';
                        }, 2000);
                    } else {
                        // Hadith element not found, trying alternative methods
                        const allHadithElements = document.querySelectorAll('[data-hadith-num]');

                        // Try alternative approaches
                        // 1. Try to find by hadithNum if it's different from reference
                        const bookmarks = JSON.parse(localStorage.getItem('hadithBookmarks')) || [];
                        const bookmark = bookmarks.find(b => {
                            const bHadithNum = normalizeHadithNum(b.hadithNum || '');
                            return bHadithNum === normalizedScrollTo || b.reference === parseInt(normalizedScrollTo);
                        });

                        if (bookmark) {
                            // Try both hadithNum and reference
                            if (bookmark.reference && bookmark.reference !== normalizedScrollTo) {
                                hadithElement = document.querySelector(`[id="ayah-${bookmark.reference}"]`);
                                if (hadithElement) {
                                    hadithElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
                                    hadithElement.style.backgroundColor = '#fff3cd';
                                    setTimeout(() => {
                                        hadithElement.style.backgroundColor = '';
                                    }, 2000);
                                    return;
                                }
                            }
                        }

                        // 2. Try to find by exact text match in the available hadith numbers (with normalization)
                        const exactMatch = Array.from(allHadithElements).find(el => {
                            const attrValue = el.getAttribute('data-hadith-num');
                            return normalizeHadithNum(attrValue) === normalizedScrollTo;
                        });
                        if (exactMatch) {
                            exactMatch.scrollIntoView({ behavior: 'smooth', block: 'center' });
                            exactMatch.style.backgroundColor = '#fff3cd';
                            setTimeout(() => {
                                exactMatch.style.backgroundColor = '';
                            }, 2000);
                            return;
                        }

                        // 3. Try to find the closest hadith number (for numeric comparison)
                        if (allHadithElements.length > 0) {
                            // Extract numeric part from normalized scrollToHadith for comparison
                            const scrollToHadithNumeric = parseInt(normalizedScrollTo.replace(/[^0-9]/g, ''));

                            if (!isNaN(scrollToHadithNumeric)) {
                                const hadithNumbers = Array.from(allHadithElements).map(el => {
                                    const attrValue = el.getAttribute('data-hadith-num');
                                    const normalizedAttr = normalizeHadithNum(attrValue);
                                    const num = parseInt(normalizedAttr.replace(/[^0-9]/g, ''));
                                    return { element: el, number: num, original: attrValue };
                                }).filter(item => !isNaN(item.number));

                                if (hadithNumbers.length > 0) {
                                    // Find the closest hadith number
                                    const closest = hadithNumbers.reduce((prev, curr) => {
                                        return (Math.abs(curr.number - scrollToHadithNumeric) < Math.abs(prev.number - scrollToHadithNumeric) ? curr : prev);
                                    });

                                    closest.element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                                    closest.element.style.backgroundColor = '#fff3cd';
                                    setTimeout(() => {
                                        closest.element.style.backgroundColor = '';
                                    }, 2000);
                                    return;
                                }
                            }
                        }
                    }
                }, 1000); // Increased timeout to ensure page is fully loaded
            }
        });

