document.addEventListener('DOMContentLoaded', function() {
    // Handle Quran/Tafsir search form
    const searchForm = document.getElementById('searchForm');
    if (searchForm) {
        searchForm.addEventListener('submit', function(e) {
        e.preventDefault();
        var type = document.getElementById('quranTypeSelect').value;
        var sura = document.getElementById('suraNoInput').value;
        var ayah = document.getElementById('ayahNoInput').value;
        var errorDiv = document.getElementById('searchError');

        if (!sura || !ayah) {
            errorDiv.textContent = 'ஸூரா மற்றும் வசன எண்களை உள்ளிடவும்';
            errorDiv.style.display = 'block';
            return;
        }

        sura = parseInt(sura);
        ayah = parseInt(ayah);

        if (sura < 1 || sura > 114) {
            errorDiv.textContent = 'ஸூரா எண் 1-114 இடையில் இருக்க வேண்டும்';
            errorDiv.style.display = 'block';
            return;
        }

        if (ayah < 1 || ayah > 286) {
            errorDiv.textContent = 'வசன எண் 1-286 இடையில் இருக்க வேண்டும்';
            errorDiv.style.display = 'block';
            return;
        }

        errorDiv.style.display = 'none';

        if (type === 'quran') {
            window.location.href = 'qurandisp.php?sura=' + sura + '&ayah=' + ayah;
        } else if (type === 'tafsir') {
            window.location.href = 'tafsiribnkathir.php?sura=' + sura + '&ayah=' + ayah;
        } else if (type === 'compare') {
            window.location.href = 'qurandispcmp.php?sura=' + sura + '&ayah=' + ayah;
        }
        });
    }

    // Handle Prophet History form
    const prophetHistoryForm = document.getElementById('prophetHistoryForm');
    if (prophetHistoryForm) {
        prophetHistoryForm.addEventListener('submit', function(e) {
        e.preventDefault();
        var sno = document.getElementById('prophetHistoryInput').value;
        var errorDiv = document.getElementById('prophetHistoryError');

        if (!sno) {
            errorDiv.textContent = 'பக்க எண்ணை உள்ளிடவும்';
            errorDiv.style.display = 'block';
            return;
        }

        sno = parseInt(sno);

        if (sno < 1 || sno > 546) {
            errorDiv.textContent = 'பக்க எண் 1-546 இடையில் இருக்க வேண்டும்';
            errorDiv.style.display = 'block';
            return;
        }

        errorDiv.style.display = 'none';
        window.location.href = 'history.php?sno=' + sno;
        });
    }

    // Handle Hadith search form (existing functionality)
    const hadithSearchForm = document.getElementById('hadithSearchForm');
    if (hadithSearchForm) {
        hadithSearchForm.addEventListener('submit', function(e) {
        e.preventDefault();
        var collection = document.getElementById('hadithCollectionSelect').value;
