            tableBody.addEventListener('click', function (e) {
                var row = e.target.closest('tr');
                if (!row) return;
                var radio = row.querySelector('input[type="radio"]');
                if (radio) {
                    radio.checked = true;
                    radio.focus();
                }
            });
        });
    });
})();








