// Make entire row clickable to select the radio inside it for hadith modal
(function () {
    document.addEventListener('DOMContentLoaded', function () {
        var modalEl = document.getElementById('hadithBookmarkModal');
        if (!modalEl) return;

        modalEl.addEventListener('shown.bs.modal', function () {
            var tableBody = document.getElementById('hadithBookmarkSlotsTable');
            if (!tableBody) return;

            tableBody.addEventListener('click', function (e) {
                var row = e.target.closest('tr');
                if (!row) return;
                var radio = row.querySelector('input[type="radio"]');
                if (radio) {
                    radio.checked = true;
                    radio.focus();
                }
            });
        });
